func (runtime backupOperationRuntime) admit(ctx context.Context,
	envelope protocol.Envelope,
) (backupOperationReply, error) {
	var request backupOperationRequest
	if err := protocol.DecodeStrict(envelope.Payload, &request, maxBackupAdmissionBytes); err != nil {
		return backupOperationReply{}, err
	}
	canonical, err := protocol.EncodeJSON(request)
	if err != nil || !bytes.Equal(canonical, envelope.Payload) ||
		(request.Action != "start" && request.Action != "abort" && request.Action != "status") ||
		!entityid.Valid(request.DatabaseID) || !entityid.Valid(request.PartitionID) ||
		request.OperationID != "" && !entityid.Valid(request.OperationID) ||
		request.HistoryCursor != "" && (request.Action != "status" || request.OperationID == "" ||
			len(request.HistoryCursor) > maxBackupAdmissionBytes) {
		return backupOperationReply{}, errors.New("backup admission request is invalid")
	}
	grant, exists := runtime.policy.grant(envelope.Actor)
	if !exists || !grant.CanOperateBackup {
		return backupOperationReply{}, errors.New("backup operation actor is unauthorized")
	}
	trusted, exists := runtime.policy.trusted(envelope.KeyID)
	if !exists || trusted.Actor != envelope.Actor {
		return backupOperationReply{}, errors.New("backup operation signer is untrusted")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{
		Region: runtime.cell, Kind: "backup.operation", Actor: trusted.Actor,
		OperationID: envelope.OperationID, Generation: 1, Epoch: envelope.Epoch,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{
		MaxLifetime: 5 * time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return backupOperationReply{}, err
	}
	if envelope.Epoch == 0 || runtime.control.Current().Epoch != envelope.Epoch {
		return backupOperationReply{}, authority.ErrFenced
	}
	if err := runtime.control.Guard(ctx, envelope.Epoch); err != nil {
		return backupOperationReply{}, err
	}
	if request.Action == "start" {
		if request.OperationID != "" {
			return backupOperationReply{}, errors.New("backup start must allocate its own operation ID")
		}
		members, placementSequence, err := runtime.currentRoster(ctx, request.DatabaseID, request.PartitionID)
		if err != nil {
			return backupOperationReply{}, err
		}
		record, sequence, err := runtime.producer.AllocatePrepare(ctx, envelope.Epoch,
			request.DatabaseID, request.PartitionID, placementSequence, members, time.Now().UTC(),
			func(check context.Context) error {
				current, currentPlacementSequence, err := runtime.currentRoster(check,
					request.DatabaseID, request.PartitionID)
				if err != nil {
					return err
				}
				if currentPlacementSequence != placementSequence || !sameBackupServingRoster(members, current) {
					return authority.ErrFenced
				}
				return nil
			})
		if err != nil {
			return backupOperationReply{}, err
		}
		return backupReplyFor(record, sequence), nil
	}
	record, sequence, err := runtime.control.ReadBackupOperation(ctx, request.DatabaseID, request.PartitionID)
	if err != nil {
		return backupOperationReply{}, err
	}
	if request.HistoryCursor != "" {
		if _, err := verifyBackupHistoryCursor(request.HistoryCursor,
			runtime.responseKey.Public().(ed25519.PublicKey), time.Now().UTC(),
			envelope.Actor, runtime.cell, request.DatabaseID, request.PartitionID,
			request.OperationID); err != nil {
			return backupOperationReply{}, err
		}
	}
	if request.Action == "status" && request.OperationID == "" {
		return runtime.backupStatusReply(ctx, record, sequence)
	}
	if request.OperationID != record.OperationID {
		if request.Action == "status" {
			return runtime.backupHistoryStatus(ctx, envelope.Actor, request)
		}
		return backupOperationReply{}, authority.ErrNotFound
	}
	if request.Action == "abort" {
		record, sequence, err = runtime.producer.BeginAbort(ctx, envelope.Epoch,
			request.DatabaseID, request.PartitionID, time.Now().UTC())
		if err != nil {
			return backupOperationReply{}, err
		}
	}
	if request.Action == "status" {
		return runtime.backupStatusReply(ctx, record, sequence)
	}
	return backupReplyFor(record, sequence), nil
}

func (runtime backupOperationRuntime) currentRoster(ctx context.Context,
	databaseID, partitionID string,
) ([]authority.BackupOperationMember, uint64, error) {
	if _, err := runtime.control.ReadTerminalIntent(ctx, databaseID, partitionID); err == nil {
		return nil, 0, authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return nil, 0, err
	}
	entry, err := runtime.control.ReadPlacementIntent(ctx, databaseID, partitionID)
	if err != nil {
		return nil, 0, err
	}
	intent, err := placement.DecodeCommittedIntent(entry.Payload)
	if err != nil || intent.DatabaseID != databaseID || intent.PartitionID != partitionID {
		return nil, 0, errors.New("backup current placement is invalid")
	}
	receipt, err := runtime.producer.Preparation.Current(ctx, databaseID, partitionID)
	if err != nil || receipt.Spec.Backup == nil || managedmaterial.VerifyIntentAgainstReceipt(intent, receipt) != nil {
		return nil, 0, errors.Join(errors.New("backup material differs from current placement"), err)
	}
	states, err := runtime.placements.ListMembers(ctx, databaseID, partitionID)
	if err != nil {
		return nil, 0, err
	}
	if len(intent.CanonicalRoster.Rows) != 2 {
		return nil, 0, errors.New("backup initial roster requires two members")
	}
	members := make([]authority.BackupOperationMember, 0, 2)
	for _, row := range intent.CanonicalRoster.Rows {
		member, found := backupServingMember(intent, row, states, runtime.memberRole)
		if !found {
			return nil, 0, errors.New("backup roster member is not serving on its exact host")
		}
		members = append(members, member)
	}
	slices.SortFunc(members, func(left, right authority.BackupOperationMember) int {
		return strings.Compare(left.Origin, right.Origin)
	})
	return members, entry.Sequence, nil
}

// backupServingMember finds the roster row's member serving on its current
// host attempt. A replaced member keeps its roster row, volume and private
// IP and serves from the host of a later attempt, so any current attempt
// counts; the replacement cleared every identity of the lost host, so a
// serving state with a host node always names the current one.
func backupServingMember(intent placement.Intent, row placement.CanonicalRosterRow,
	states []placement.VersionedMemberState, role string,
) (authority.BackupOperationMember, bool) {
	for _, versioned := range states {
		state := versioned.State
		if state.CanonicalRosterRow == row && state.Stage == placement.StageServing &&
			state.HostNode != "" && state.HostAttempt >= 1 &&
			state.IntentGeneration == intent.Generation &&
			state.IntentPayloadDigest == intent.PayloadDigest() {
			return authority.BackupOperationMember{
				Origin:   authority.BackupMemberOrigin(row.MemberID, row.Incarnation),
				MemberID: row.MemberID, Incarnation: row.Incarnation,
				TLSLeafSHA256: row.TLSLeafSHA256, Node: state.HostNode, Role: role}, true
		}
	}
	return authority.BackupOperationMember{}, false
}

func sameBackupServingRoster(left, right []authority.BackupOperationMember) bool {
	if len(left) != len(right) {
		return false
	}
	for index := range left {
		first, second := left[index], right[index]
		if first.Origin != second.Origin || first.MemberID != second.MemberID ||
			first.Incarnation != second.Incarnation || first.TLSLeafSHA256 != second.TLSLeafSHA256 ||
			first.Node != second.Node || first.Role != second.Role {
			return false
		}
	}
	return true
}

func (producer BackupOperationProducer) AllocatePrepare(ctx context.Context, epoch uint64,
	database, partition string, placementSequence uint64,
	members []authority.BackupOperationMember, now time.Time,
	verify func(context.Context) error,
) (authority.BackupOperationRecord, uint64, error) {
	if producer.Store == nil || epoch == 0 || placementSequence == 0 || now.IsZero() || verify == nil {
		return authority.BackupOperationRecord{}, 0, errors.New("backup operation producer is incomplete")
	}
	receipt, manifest, signer, err := currentBackupSigner(ctx, producer.Preparation, database, partition)
	if err != nil {
		return authority.BackupOperationRecord{}, 0, err
	}
	return producer.allocatePrepareWithMaterial(ctx, epoch, database, partition,
		placementSequence, members, now, receipt, manifest, signer, verify)
}

// allocatePrepareWithMaterial is the allocation core after CurrentBundle has
// authenticated the pinned receipt and retained signer. It is kept separate
// so the real-process bridge can feed the Rust fixture's exact authenticated
// material pins through the same R3 commit and signing path.
func (producer BackupOperationProducer) allocatePrepareWithMaterial(ctx context.Context, epoch uint64,
	database, partition string, placementSequence uint64,
	members []authority.BackupOperationMember, now time.Time,
	receipt PreparationReceipt, manifest BackupManifestPayload, signer ed25519.PrivateKey,
	verify func(context.Context) error,
) (authority.BackupOperationRecord, uint64, error) {
	if producer.Store == nil || epoch == 0 || placementSequence == 0 || now.IsZero() || verify == nil ||
		len(signer) != ed25519.PrivateKeySize ||
		manifest.SignerKeyID != backupKeyID(signer.Public().(ed25519.PublicKey)) ||
		manifest.SourceAuthoritySHA256 != receipt.AuthoritySHA256 ||
		manifest.SourceConfigurationID != receipt.AuthorityConfigurationID {
		return authority.BackupOperationRecord{}, 0, ErrMaterialConflict
	}
	if err := validateBackupRoster(receipt, members); err != nil {
		return authority.BackupOperationRecord{}, 0, err
	}
	prior, expected, err := producer.Store.ReadBackupOperation(ctx, database, partition)
	if err != nil && !errors.Is(err, authority.ErrNotFound) {
		return authority.BackupOperationRecord{}, 0, err
	}
	if err == nil && (prior.State != "aborted" && prior.State != "complete" ||
		prior.SourceAuthoritySHA256 != manifest.SourceAuthoritySHA256 || prior.BackupSet != manifest.BackupSet ||
		prior.State == "aborted" && prior.AttemptHighWater == math.MaxUint64 ||
		prior.State == "complete" && prior.Ordinal == math.MaxUint64) {
		return authority.BackupOperationRecord{}, 0, authority.ErrInvalidTransition
	}
	attempt := uint64(1)
	ordinal := uint64(1)
	completed := uint64(0)
	var terminal []authority.BackupTerminalReceipt
	if expected != 0 {
		completed = prior.CompletedOrdinal
		if prior.State == "aborted" {
			attempt = prior.AttemptHighWater + 1
			ordinal = prior.Ordinal
		} else {
			ordinal = prior.Ordinal + 1
		}
		terminal = append(slices.Clone(prior.Terminal), authority.BackupTerminalReceipt{
			OperationID: prior.OperationID, Ordinal: prior.Ordinal, Attempt: prior.Attempt, State: prior.State})
		if len(terminal) > 1024 {
			terminal = terminal[len(terminal)-1024:]
		}
	}
	var nonce [16]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return authority.BackupOperationRecord{}, 0, err
	}
	operationID := entityid.New()
	// Rust Prepare can spend two sequential 60-second stages producing a
	// durable Cut. Leave room for both stages and host polling, while staying
	// below the member's five-minute maximum signed-envelope lifetime.
	expires := now.Add(4 * time.Minute).UnixMilli()
	if expires <= 0 {
		return authority.BackupOperationRecord{}, 0, errors.New("backup prepare expiry is invalid")
	}
	roster := make([]backupRosterWire, len(members))
	for index, member := range members {
		roster[index] = backupRosterWire{member.Origin, member.MemberID, member.Incarnation}
	}
	prepare, err := signBackupOperation(backupPrepareDomain, backupPrepareWire{
		Version: 1, OperationID: operationID, Nonce: hex.EncodeToString(nonce[:]),
		SourceScopeDigest: manifest.SourceScopeDigest, SourceAuthoritySHA256: manifest.SourceAuthoritySHA256,
		SourceConfigurationID: manifest.SourceConfigurationID, SourceTargetDigest: manifest.SourceTargetDigest,
		BackupSet: manifest.BackupSet, BackupTargetDigest: manifest.BackupTargetDigest,
		Ordinal: ordinal, Attempt: attempt, ExpiresAtMS: uint64(expires), SignerKeyID: manifest.SignerKeyID,
		Roster: roster}, signer)
	if err != nil {
		return authority.BackupOperationRecord{}, 0, err
	}
	record := authority.BackupOperationRecord{Version: 1, DatabaseID: database,
		PartitionID: partition, PlacementSequence: placementSequence,
		SourceScopeDigest: manifest.SourceScopeDigest, SourceAuthoritySHA256: manifest.SourceAuthoritySHA256,
		SourceConfigurationID: manifest.SourceConfigurationID, SourceTargetDigest: manifest.SourceTargetDigest,
		BackupSet: manifest.BackupSet, BackupTargetDigest: manifest.BackupTargetDigest,
		OwnerMemberID: manifest.OwnerMemberID, OwnerIncarnation: manifest.OwnerIncarnation,
		CompletedOrdinal: completed, Ordinal: ordinal, Attempt: attempt,
		AttemptHighWater: attempt, OperationID: operationID,
		Nonce: hex.EncodeToString(nonce[:]), PrepareEnvelope: prepare,
		PrepareExpiresAtMS: uint64(expires), State: "accepted",
		Roster: slices.Clone(members), Terminal: terminal}
	verifiedStore, ok := producer.Store.(verifiedBackupOperationStore)
	if !ok {
		return authority.BackupOperationRecord{}, 0, errors.New("backup operation store lacks final admission verification")
	}
	sequence, err := verifiedStore.CommitBackupOperationVerified(ctx, epoch,
		database, partition, expected, record, verify)
	return producer.confirmBackupCommit(ctx, database, partition, record, sequence, err)
}

func (r *Runtime) ReadBackupOperation(ctx context.Context, databaseID, partitionID string) (BackupOperationRecord, uint64, error) {
	key, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return BackupOperationRecord{}, 0, err
	}
	entry, err := r.ReadHostMutation(ctx, MutationBackupOperation, key)
	if err != nil {
		return BackupOperationRecord{}, 0, err
	}
	record, err := decodeBackupRecord(entry.Payload, databaseID, partitionID)
	return record, entry.Sequence, err
}

func (r *Reader) ReadBackupOperation(ctx context.Context, databaseID, partitionID string) (BackupOperationRecord, uint64, error) {
	key, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return BackupOperationRecord{}, 0, err
	}
	entry, err := r.ReadHostMutation(ctx, MutationBackupOperation, key)
	if err != nil {
		return BackupOperationRecord{}, 0, err
	}
	record, err := decodeBackupRecord(entry.Payload, databaseID, partitionID)
	return record, entry.Sequence, err
}

// CommitBackupOperation verifies the monotonic transition, then uses the same
// global lease/subject CAS and exact unknown-publish readback as placement.
func (r *Runtime) CommitBackupOperation(ctx context.Context, epoch uint64,
	databaseID, partitionID string, expectedSequence uint64, next BackupOperationRecord,
) (uint64, error) {
	return r.CommitBackupOperationVerified(ctx, epoch, databaseID, partitionID,
		expectedSequence, next, nil)
}

// CommitBackupOperationVerified adds a caller-owned final check to new
// operation admission. The check runs under the same authority mutation lock
// as the backup and managed-update R3 compare-and-set.
func (r *Runtime) CommitBackupOperationVerified(ctx context.Context, epoch uint64,
	databaseID, partitionID string, expectedSequence uint64, next BackupOperationRecord,
	callerVerify func(context.Context) error,
) (uint64, error) {
	key, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return 0, err
	}
	if next.DatabaseID != databaseID || next.PartitionID != partitionID {
		return 0, ErrInvalidTransition
	}
	var prior *BackupOperationRecord
	current, sequence, err := r.ReadBackupOperation(ctx, databaseID, partitionID)
	if err == nil {
		prior = &current
	} else if !errors.Is(err, ErrNotFound) {
		return 0, err
	}
	if sequence != expectedSequence {
		return 0, ErrConflict
	}
	newOperation := prior == nil || next.OperationID != prior.OperationID
	if newOperation && callerVerify == nil {
		return 0, ErrFenced
	}
	if err := validateBackupTransition(prior, next); err != nil {
		return 0, err
	}
	payload, err := json.Marshal(next)
	if err != nil || len(payload) > maxControlPayload {
		return 0, errors.New("backup operation control payload exceeds bound")
	}
	release, err := r.beginWorkloadGate(ctx, WorkloadScope{DatabaseID: databaseID, PartitionID: partitionID})
	if err != nil {
		return 0, err
	}
	defer release()
	if err := r.requireNoTerminalIntent(ctx, databaseID, partitionID); err != nil {
		return 0, err
	}
	digest := sha256.Sum256(payload)
	mutationID := entityid.Derive("backup-mutation", hex.EncodeToString(digest[:]))
	var verify func(context.Context) error
	if newOperation {
		verify = func(check context.Context) error {
			placement, err := r.ReadPlacementIntent(check, databaseID, partitionID)
			if err != nil {
				return err
			}
			if placement.Sequence != next.PlacementSequence {
				return ErrFenced
			}
			if err := r.requireNoActiveManagedUpdate(check, databaseID, partitionID); err != nil {
				return err
			}
			if err := r.requireNoTerminalIntent(check, databaseID, partitionID); err != nil {
				return err
			}
			if callerVerify != nil {
				return callerVerify(check)
			}
			return nil
		}
	}
	committed, err := r.commitMutationVerified(ctx, epoch, MutationBackupOperation,
		key, mutationID, expectedSequence, payload, verify)
	if err != nil {
		return 0, err
	}
	observed, observedSequence, err := r.ReadBackupOperation(ctx, databaseID, partitionID)
	if err != nil || observedSequence != committed {
		return 0, fmt.Errorf("%w: backup operation readback: %v", ErrOutcomeUnknown, err)
	}
	wire, err := json.Marshal(observed)
	if err != nil || !bytes.Equal(wire, payload) {
		return 0, ErrOperationConflict
	}
	return committed, nil
}

func (r *Runtime) commitMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, nil)
}

func (r *Runtime) commitMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil {
		return 0, ErrNotLeader
	}
	if r.checkClock() != nil {
		return 0, ErrClockUnhealthy
	}
	if err := validateMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return 0, ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		return 0, ErrFenced
	}

	subject := mutationSubject(r.config.Scope, kind, subjectKey)
	for range 8 {
		info, err := r.stream.Info(ctx)
		if err != nil {
			return 0, fmt.Errorf("read control log sequence: %w", err)
		}
		if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
			return 0, fmt.Errorf("validate control log consistency: %w", err)
		}
		leaseEntry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-unreadable"})
			return 0, err
		}
		if leaseEntry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(leaseEntry.Data)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-corrupt"})
			return 0, ErrLeaseCorrupt
		}
		if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released ||
			!time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, Epoch: lease.Epoch, Revision: leaseEntry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
			return 0, ErrFenced
		}

		existing, err := r.stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			existing = nil
		} else if err != nil {
			return 0, fmt.Errorf("read prior host mutation: %w", err)
		}
		if existing != nil && existing.Sequence > info.State.LastSeq {
			continue
		}
		if existing != nil {
			prior, decodeErr := decodeControlRecord(existing.Data)
			if decodeErr != nil {
				return 0, fmt.Errorf("decode prior host mutation: %w", decodeErr)
			}
			if prior.OperationID == operationID {
				if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
					return existing.Sequence, nil
				}
				return 0, ErrOperationConflict
			}
			if existing.Sequence != expectedSubjectSequence {
				return 0, ErrConflict
			}
		} else if expectedSubjectSequence != 0 {
			return 0, ErrConflict
		}
		if verify != nil {
			if err := r.verify(ctx, expectedEpoch, leaseEntry.Sequence, info.State.LastSeq,
				subject, operationID, leaseEntry.Time.Add(time.Duration(lease.LeaseDuration)), verify); err != nil {
				return 0, err
			}
			if !time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
				return 0, ErrFenced
			}
		}

		record := controlRecord{
			Version: 1, Kind: kind, Scope: r.config.Scope, SubjectKey: subjectKey,
			OperationID: operationID, Epoch: expectedEpoch, Payload: bytes.Clone(payload),
		}
		data, err := json.Marshal(record)
		if err != nil {
			return 0, err
		}
		msg := controlMessage(subject, string(kind), operationID, data)
		ack, err := r.js.PublishMsg(ctx, msg,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSubjectSequence, subject),
		)
		if err == nil {
			return ack.Sequence, nil
		}
		if isSequenceConflict(err) {
			latest, readErr := r.stream.GetLastMsgForSubject(ctx, subject)
			if readErr == nil {
				prior, decodeErr := decodeControlRecord(latest.Data)
				if decodeErr == nil && prior.OperationID == operationID {
					if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
						return latest.Sequence, nil
					}
					return 0, ErrOperationConflict
				}
				if latest.Sequence != expectedSubjectSequence {
					return 0, ErrConflict
				}
			}
			continue
		}
		return r.resolveUnknownMutation(ctx, subject, kind, subjectKey, operationID, expectedEpoch, payload, err)
	}
	return 0, ErrConflict
}

// ReadHostMutation reads the current committed host record.
func (r *Runtime) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

func (r *Runtime) CommitPlacementIntent(
	ctx context.Context,
	expectedEpoch uint64,
	databaseID string,
	partitionID string,
	operationID string,
	expectedSequence uint64,
	payload []byte,
) (uint64, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return 0, err
	}
	if err := validateMutation(MutationPlacementIntent, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	release, err := r.beginWorkloadGate(ctx, WorkloadScope{DatabaseID: databaseID, PartitionID: partitionID})
	if err != nil {
		return 0, err
	}
	defer release()
	if err := r.requireNoTerminalIntent(ctx, databaseID, partitionID); err != nil {
		return 0, err
	}
	return r.commitMutationVerified(ctx, expectedEpoch, MutationPlacementIntent,
		subjectKey, operationID, expectedSequence, payload, func(check context.Context) error {
			return r.requireNoActiveBackup(check, databaseID, partitionID)
		})
}

func (r *Runtime) ReadPlacementIntent(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, MutationPlacementIntent, subjectKey)
}

func (r *Runtime) CommitMaterialReceipt(ctx context.Context, expectedEpoch uint64,
	databaseID, partitionID, operationID string, expectedSequence uint64, payload []byte,
) (uint64, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return 0, err
	}
	if err := validateMutation(MutationMaterialReceipt, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	return r.commitMutation(ctx, expectedEpoch, MutationMaterialReceipt, subjectKey, operationID, expectedSequence, payload)
}

func (r *Runtime) ReadMaterialReceipt(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, MutationMaterialReceipt, subjectKey)
}

func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

