func superviseControllerAdmission(ctx context.Context, cfg Config, commandName, executable string) error {
	return superviseControllerAdmissionWithAuthority(ctx, cfg, commandName, executable, nil)
}

func superviseControllerAdmissionWithAuthority(ctx context.Context, cfg Config, commandName, executable string, authority *rootOCIAuthority) error {
	if commandName != "bootstrap-admit-initial" && commandName != "bootstrap-admit-restart" || executable == "" {
		return errors.New("invalid controller admission child command")
	}
	if authority != nil && (commandName != "bootstrap-admit-restart" || os.Geteuid() != 0) {
		return errors.New("registered admission requires the root restart supervisor")
	}
	// The child digests the exact signed bytes, not a re-encoding.
	wire, err := cfg.signedWire()
	if err != nil || len(wire) == 0 || len(wire) > maxConfigBytes {
		return errors.New("encode bounded controller admission configuration")
	}
	childCtx, cancel := context.WithTimeout(ctx, controllerAdmissionTimeout)
	defer cancel()
	child := exec.CommandContext(childCtx, executable, commandName)
	stdin, err := child.StdinPipe()
	if err != nil {
		return err
	}
	defer stdin.Close()
	child.Stdout = io.Discard
	// Admission errors carry no secret values; keep them in the unit journal.
	child.Stderr = os.Stderr
	child.Env = []string{"PATH=/usr/bin:/bin", "LANG=C"}
	child.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	if commandName == "bootstrap-admit-restart" && os.Geteuid() == 0 {
		uid, gid, err := controllerServiceIdentity()
		if err != nil {
			return err
		}
		child.SysProcAttr.Credential = &syscall.Credential{Uid: uid, Gid: gid, Groups: []uint32{}}
	}
	child.Cancel = func() error {
		if err := syscall.Kill(-child.Process.Pid, syscall.SIGKILL); err != nil {
			if errors.Is(err, syscall.ESRCH) {
				return os.ErrProcessDone
			}
			return err
		}
		return nil
	}
	child.WaitDelay = 5 * time.Second
	if err := child.Start(); err != nil {
		return fmt.Errorf("start controller admission child: %w", err)
	}
	if authority != nil {
		unregister, err := authority.registerAdmissionChild(child.Process.Pid)
		if err != nil {
			cancel()
			_ = child.Wait()
			return fmt.Errorf("register exact controller admission child: %w", err)
		}
		defer unregister()
	}
	if _, err := stdin.Write(wire); err != nil {
		cancel()
		_ = child.Wait()
		return fmt.Errorf("deliver controller admission configuration: %w", err)
	}
	if err := stdin.Close(); err != nil {
		cancel()
		_ = child.Wait()
		return err
	}
	err = child.Wait()
	if ctxErr := childCtx.Err(); ctxErr != nil {
		return fmt.Errorf("controller admission exceeded its startup deadline: %w", ctxErr)
	}
	if err != nil {
		return fmt.Errorf("controller admission child failed: %w", err)
	}
	return nil
}

func runControllerAdmissionChild(ctx context.Context, commandName string, input io.Reader) error {
	wire, err := io.ReadAll(io.LimitReader(input, maxConfigBytes+1))
	if err != nil || len(wire) == 0 || len(wire) > maxConfigBytes {
		return errors.New("controller admission child configuration is invalid")
	}
	cfg, err := decodeConfig(wire)
	if err != nil {
		return fmt.Errorf("decode controller admission child configuration: %w", err)
	}
	ctx, cancel := context.WithTimeout(ctx, controllerAdmissionTimeout)
	defer cancel()
	switch commandName {
	case "bootstrap-admit-initial":
		if os.Geteuid() != 0 {
			return errors.New("initial controller admission requires root")
		}
		return admitProductionControllerRoot(ctx, cfg)
	case "bootstrap-admit-restart":
		uid, gid, err := controllerServiceIdentity()
		if err != nil {
			return err
		}
		if os.Geteuid() != int(uid) || os.Getegid() != int(gid) {
			return errors.New("controller restart admission child requires the dedicated service account")
		}
		return admitProductionControllerRestart(ctx, cfg)
	default:
		return errors.New("unknown controller admission child command")
	}
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

// decodeConfig strictly decodes config bytes and keeps them as the config's wire.
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

// signedWire returns the exact bytes the config was read from, or its
// canonical encoding when code built it.
func (c Config) signedWire() ([]byte, error) {
	if c.wire != nil {
		return c.wire, nil
	}
	if c.Version != 0 && c.Version != ConfigVersion {
		return nil, fmt.Errorf("unsupported config version %d; want %d", c.Version, ConfigVersion)
	}
	c.Version = ConfigVersion
	return protocol.EncodeJSON(c)
}

func writeAdmissionShell(t *testing.T, script string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "admission-child.sh")
	if err := os.WriteFile(path, []byte(script), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, 0o755); err != nil {
		t.Fatal(err)
	}
	return path
}

func shellQuote(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
}

func bootstrapAdmissionCapabilitiesMatch(t *testing.T, want uint64) bool {
	t.Helper()
	file, err := os.Open("/proc/self/status")
	if err != nil {
		return false
	}
	defer file.Close()
	values := make(map[string]string)
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		key, value, ok := strings.Cut(scanner.Text(), ":")
		if ok {
			values[key] = strings.TrimSpace(value)
		}
	}
	if err := scanner.Err(); err != nil || values["NoNewPrivs"] != "1" {
		return false
	}
	for _, key := range []string{"CapEff", "CapPrm", "CapBnd"} {
		got, err := strconv.ParseUint(values[key], 16, 64)
		if err != nil || got != want {
			return false
		}
	}
	return true
}

func processState(pid int) (rune, error) {
	data, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
	if err != nil {
		return 0, err
	}
	end := strings.LastIndex(string(data), ")")
	if end < 0 {
		return 0, errors.New("invalid process stat entry")
	}
	fields := strings.Fields(string(data[end+1:]))
	if len(fields) == 0 || len(fields[0]) != 1 {
		return 0, errors.New("invalid process state field")
	}
	return rune(fields[0][0]), nil
}

