func controllerServiceIdentity() (uint32, uint32, error) {
	account, err := user.Lookup(controllerServiceUser)
	if err != nil {
		return 0, 0, fmt.Errorf("look up dedicated controller service account: %w", err)
	}
	uid, uidErr := strconv.ParseUint(account.Uid, 10, 32)
	gid, gidErr := strconv.ParseUint(account.Gid, 10, 32)
	if uidErr != nil || gidErr != nil || uid == 0 || gid == 0 {
		return 0, 0, errors.New("dedicated controller service UID/GID is invalid")
	}
	return uint32(uid), uint32(gid), nil
}

func acceptedControllerAdmissionGate(cfg Config, markers bootstrapstart.MarkerStore, clockCheck func() error) (bootstrapstart.Gate, bootstrapstart.AcceptedIdentity, error) {
	fail := func(err error) (bootstrapstart.Gate, bootstrapstart.AcceptedIdentity, error) {
		return bootstrapstart.Gate{}, bootstrapstart.AcceptedIdentity{}, err
	}
	accepted, err := markers.ReadIdentity()
	if err != nil {
		return fail(fmt.Errorf("read accepted controller identity: %w", err))
	}
	if cfg.NATS.Cell != strings.ToLower(accepted.Cell) || cfg.NATS.Instance != accepted.Slot ||
		cfg.Controller.CandidateID != entityid.Derive("controller", accepted.DeploymentID, accepted.Cell, accepted.Slot) {
		return fail(errors.New("controller configuration differs from accepted deployment and slot"))
	}
	if err := bootstrapstart.CheckIdentityRekeyPrestart(accepted); err != nil {
		return fail(err)
	}
	inputs, err := bootstrapstart.LoadTrustInputs(accepted)
	if err != nil {
		return fail(err)
	}
	loadedWire, err := cfg.signedWire()
	if err != nil {
		return fail(err)
	}
	serviceUID, serviceGID, err := controllerServiceIdentity()
	if err != nil {
		return fail(err)
	}
	if os.Geteuid() != int(serviceUID) || os.Getegid() != int(serviceGID) {
		return fail(errors.New("accepted controller admission requires the dedicated service account"))
	}
	checker, err := bootstrapstart.NewLiveCredentialChecker(cfg.NATS, serviceUID, serviceGID,
		cfg.Controller.ResponseKeyFile, cfg.Controller.BrokerTicketKeyFile, cfg.Controller.HostNATSIssuerSeedFile,
		cfg.Controller.HostTLSIssuerKeyFile, cfg.Controller.HostTLSIssuerCertFile, func() error {
			if _, err := readPrivateKey(cfg.Controller.ResponseKeyFile); err != nil {
				return err
			}
			_, _, err := brokerTicketKeys(cfg)
			return err
		})
	if err != nil {
		return fail(err)
	}
	checker.TerraBaseCACertFile, checker.TerraBaseCAKeyFile = cfg.Controller.TerraBaseCACertFile, cfg.Controller.TerraBaseCAKeyFile
	checker.ControllerConfig = loadedWire
	material, err := bootstrapstart.NewMaterialStore(nil, serviceUID, serviceGID)
	if err != nil {
		return fail(err)
	}
	return bootstrapstart.Gate{Roots: inputs.Roots.Historical, LoadedControllerConfigSHA256: controllerSHA256(loadedWire),
		LoadedControllerConfig: loadedWire, Descriptor: bootstrapstart.NewIMDSClient(), Material: material, Credentials: checker,
		Markers: markers, ClockCheck: clockCheck, ObserveIdentity: controllerIdentityObserver(cfg),
		SelfUpdate: selfupdate.NewLayout(selfUpdateRoot(cfg.Controller.SelfUpdateRoot))}, accepted, nil

func offlineRestartAdmission(cfg Config) (bool, error) {
	return controllerMarkerPresent()
}

// startControllerAdmission admits initial starts before NATS starts.
// Accepted production restarts first pass local proof, then repeat full
// admission in the background; it gates everything except route formation.
// An interrupted material install was finished before this process started
// by selfupdate prepare: this process cannot write its credential directory.
func startControllerAdmission(ctx context.Context, cfg Config, clockCheck func() error) (*controllerAdmission, error) {
	offline, err := offlineRestartAdmission(cfg)
	if err != nil {
		return nil, err
	}
	admission := &controllerAdmission{offline: offline, done: make(chan struct{})}
	if !offline {
		if err := admitControllerBootstrap(ctx, cfg, clockCheck); err != nil {
			return nil, err
		}
		close(admission.done)
		return admission, nil
	}
	if err := controllerLocalAdmissionProduction(ctx, cfg); err != nil {
		return nil, fmt.Errorf("offline controller restart admission: %w", err)
	}
	log.Printf("controller %s passed local restart admission; starting broker routes before OCI re-verification", cfg.NATS.Instance)
	runCtx, cancel := context.WithCancel(ctx)
	admission.cancel, admission.stopped = cancel, make(chan struct{})
	go func() {
		defer close(admission.stopped)
		backoff := controllerAdmissionMinBackoff
		for attempt := 1; ; attempt++ {
			err := admitControllerBootstrap(runCtx, cfg, clockCheck)
			if err == nil {
				log.Printf("controller %s passed full restart admission after %d attempt(s)", cfg.NATS.Instance, attempt)
				close(admission.done)
				return
			}
			if runCtx.Err() != nil {
				return
			}
			delay := backoff + time.Duration(rand.Int64N(int64(backoff)/5+1))
			log.Printf("full controller restart admission attempt %d: %v; authority held, broker routes stay up, retrying in %s",
				attempt, err, delay.Round(time.Second))
			backoff = min(backoff*2, controllerAdmissionMaxBackoff)
			select {
			case <-runCtx.Done():
				return
			case <-time.After(delay):
			}
		}
	}()
	return admission, nil
}

func controllerClockCheck(probe brokerauth.ClockProbe) func() error {
	return func() error {
		_, err := brokerauth.MeasureHealthyClock(probe)
		return err
	}
}

func runController(ctx context.Context, cfg Config, output io.Writer) (err error) {
	// Take the systemd notification socket before any child process starts.
	notifier := sdnotify.FromEnvironment()
	defer func() { _ = notifier.Stopping() }()
	telemetry, err := startRuntimeObservability(ctx, cfg, "controller", cfg.NATS.Instance)
	if err != nil {
		return fmt.Errorf("start controller observability: %w", err)
	}
	defer telemetry.close()
	clockProbe := controllerBrokerClockProbe()
	clockCheck := controllerClockCheck(clockProbe)
	admission, err := startControllerAdmission(ctx, cfg, clockCheck)
	if err != nil {
		return err
	}
	defer admission.stop()
	if cfg.NATS.Embedded == nil {
		return errors.New("controller run requires an embedded regional NATS server")
	}

func (store MarkerStore) openDirectory() (int, error) {
	if !filepath.IsAbs(store.directory) || filepath.Clean(store.directory) != store.directory {
		return -1, ErrInvalidMarker
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(store.directory, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrInvalidMarker
		}
		next, openErr := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		unix.Close(fd)
		if openErr != nil {
			return -1, fmt.Errorf("open accepted-install directory component: %w", openErr)
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrInvalidMarker
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != store.ownerUID ||
		stat.Gid != 0 && store.ownerUID == 0 || stat.Mode&0o777 != 0o755 {
		unix.Close(fd)
		return -1, ErrInvalidMarker
	}
	return fd, nil
}

func (store MarkerStore) ReadIdentity() (AcceptedIdentity, error) {
	dir, err := store.openDirectory()
	if err != nil {
		return AcceptedIdentity{}, err
	}
	defer unix.Close(dir)
	wire, err := store.readIdentityBytes(dir, markerName)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	return DecodeAcceptedIdentity(wire)
}

func (store MarkerStore) readIdentityBytes(dir int, name string) ([]byte, error) {
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 || stat.Mode&0o7777 != 0o644 ||
		stat.Nlink != 1 || stat.Size <= 0 || stat.Size > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	wire, err := io.ReadAll(io.LimitReader(file, MaxAcceptedIdentityBytes+1))
	if err != nil || len(wire) == 0 || len(wire) > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	return wire, nil
}

func IdentityRekeyJournalPresent() (bool, error) {
	_, err := NewMarkerStore().readIdentityRekeyJournal()
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return true, err
	}
	return true, nil
}

// LoadBakedInputs reads only the fixed production paths. Tests use the private
// bakedStore seam to exercise modes and symlink handling in temporary trees.
func LoadBakedInputs() (BakedInputs, error) {
	return bakedStore{directory: BakedDirectory, chainFile: RootChainFile, ownerUID: 0, ownerGID: 0}.load()
}

// LoadImageRoots reads only the existing fixed root-owned image root inventory.
// Finite qualification verifies its own signed purpose without a production identity.
func LoadImageRoots() (trust.Keyring, error) {
	return bakedStore{directory: BakedDirectory, ownerUID: 0, ownerGID: 0}.loadRoots()
}

// BakedInputsPresent is a routing check, not validation. Any object at the
// fixed path, including an invalid file or symlink, requires production
// admission and therefore fails through LoadBakedInputs. Only an absent path
// permits an explicitly configured lab runtime.
func BakedInputsPresent() (bool, error) {
	_, err := os.Lstat(BakedDirectory)
	if err == nil {
		return true, nil
	}
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return false, err

func (store bakedStore) load() (BakedInputs, error) {
	dir, err := store.openDirectory(store.directory)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("open baked bootstrap directory: %w", err)
	}
	defer unix.Close(dir)
	identityWire, err := store.readFile(dir, identityFilename, maxIdentity)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("read baked identity: %w", err)
	}
	identity, err := parseBakedIdentity(identityWire)
	if err != nil {
		return BakedInputs{}, err
	}
	anchorWire, err := store.readFile(dir, anchorFilename, bootstrap.MaxBootstrapAnchorBytes)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("read baked anchor: %w", err)
	}
	if _, err := trust.DecodeEnvelope(anchorWire); err != nil {
		return BakedInputs{}, fmt.Errorf("decode baked anchor: %w", err)
	}
	genesis, err := store.loadRoots()
	if err != nil {
		return BakedInputs{}, err
	}
	chain, err := readRootChain(store.chainFile)
	if err != nil {
		return BakedInputs{}, err
	}
	verified, err := trust.VerifyRootChain(genesis, identity.ChainIdentity(), chain)
	if err != nil {
		return BakedInputs{}, fmt.Errorf("verify adopted root chain: %w", err)
	}
	return BakedInputs{Identity: identity, Genesis: genesis, Chain: chain, Roots: verified.Historical,
		AnchorWire: anchorWire}, nil
}

