func NewLiveCredentialChecker(cfg natscell.Config, serviceUID, serviceGID uint32,
	responseKeyFile, brokerTicketKeyFile, hostNATSIssuerSeedFile, hostTLSIssuerKeyFile, hostTLSIssuerCertFile string,
	validateControllerKeys func() error,
) (LiveCredentials, error) {
	if serviceUID == 0 || serviceGID == 0 || cfg.Embedded == nil ||
		responseKeyFile == "" || brokerTicketKeyFile == "" || hostNATSIssuerSeedFile == "" ||
		hostTLSIssuerKeyFile == "" || hostTLSIssuerCertFile == "" || validateControllerKeys == nil {
		return LiveCredentials{}, ErrLiveCredentials
	}
	return LiveCredentials{Config: cfg, ServiceUID: serviceUID, ServiceGID: serviceGID,
		ResponseKeyFile: responseKeyFile, BrokerTicketKeyFile: brokerTicketKeyFile,
		HostNATSIssuerSeedFile: hostNATSIssuerSeedFile, HostTLSIssuerKeyFile: hostTLSIssuerKeyFile,
		HostTLSIssuerCertFile:  hostTLSIssuerCertFile,
		ValidateControllerKeys: validateControllerKeys, directory: MaterialDirectory}, nil
}

func (check LiveCredentials) VerifyLiveCredentials(ctx context.Context, expected MaterialPins, accepted AcceptedIdentity) error {
	acceptance, err := accepted.AcceptanceSHA256()
	if err != nil || expected.acceptance != acceptance || !expected.matchesAccepted(accepted) {
		return ErrLiveCredentials
	}
	return check.verifyLiveCredentials(ctx, expected, accepted.Slot, accepted.SeedSlot, accepted.MaterialReferences)
}

// VerifyInitialLiveCredentials is limited to current, independently verified first formation.
func (check LiveCredentials) VerifyInitialLiveCredentials(ctx context.Context, expected MaterialPins, manifest bootstrap.StartupAuthority) error {
	payload := manifest.Manifest()
	if !sameMaterials(expectedMaterials(payload, payload.Slot), expected.Digests) {
		return ErrLiveCredentials
	}
	expected.references = slotReferences(payload, payload.Slot)
	return check.verifyLiveCredentials(ctx, expected, payload.Slot, payload.SeedSlot, payload.Secrets)
}

func (check LiveCredentials) verifyLiveCredentials(ctx context.Context, expected MaterialPins, slot, seedSlot string, references []bootstrap.SecretReference) error {
	if check.ServiceUID == 0 || check.ServiceGID == 0 || check.Config.Embedded == nil ||
		check.ValidateControllerKeys == nil ||
		len(expected.Digests) == 0 {
		return ErrLiveCredentials
	}
	if err := check.verifyPaths(expected, slot, seedSlot, references); err != nil {
		return err
	}
	if err := check.verifyInventory(expected); err != nil {
		return err
	}
	if os.Geteuid() == int(check.ServiceUID) && os.Getegid() == int(check.ServiceGID) {
		if err := natscell.ValidateProductionCredentials(check.Config); err != nil {
			return err
		}
		return check.ValidateControllerKeys()
	}
	if os.Geteuid() != 0 {
		return fmt.Errorf("%w: credential verifier is neither root nor the service account", ErrLiveCredentials)
	}
	wire, err := protocol.EncodeJSON(CredentialChildRequest{
		Config: check.Config, UID: check.ServiceUID, GID: check.ServiceGID,
		ResponseKeyFile: check.ResponseKeyFile, BrokerTicketKeyFile: check.BrokerTicketKeyFile,
	})
	if err != nil {
		return fmt.Errorf("encode service credential preflight: %w", err)
	}
	run := check.runChild
	if run == nil {
		run = runCredentialChild
	}
	childCtx, cancel := context.WithTimeout(ctx, credentialChildTimeout)
	defer cancel()
	if err := run(childCtx, wire, check.ServiceUID, check.ServiceGID); err != nil {
		return fmt.Errorf("%w: service-account credential preflight: %v", ErrLiveCredentials, err)
	}
	return check.verifyInventory(expected)
}

func (check LiveCredentials) verifyInventory(expected MaterialPins) error {
	dir, err := openMaterialDirectory(check.directory, check.ServiceUID, check.ServiceGID, 0o700, check.allowUnsafeAncestors)
	if err != nil {
		return fmt.Errorf("%w: open fixed credential directory: %v", ErrLiveCredentials, err)
	}
	defer unix.Close(dir)
	copyFD, err := unix.Dup(dir)
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(copyFD), check.directory)
	entries, err := file.ReadDir(-1)
	_ = file.Close()
	if err != nil || len(entries) != expected.size() {
		return fmt.Errorf("%w: installed credential inventory differs", ErrLiveCredentials)
	}
	for _, entry := range entries {
		if !expected.known(entry.Name()) {
			return fmt.Errorf("%w: unpinned credential file", ErrLiveCredentials)
		}
		var content []byte
		var err error
		if want := expected.Digests[entry.Name()]; want != "" {
			content, err = readMaterial(dir, entry.Name(), check.ServiceUID, check.ServiceGID, want, bootstrap.MaxSecretBytes)
		} else {
			// Issued files were checked by rule in VerifyRestart.
			content, err = readUnpinned(dir, entry.Name(), check.ServiceUID, check.ServiceGID, bootstrap.MaxSecretBytes)
		}
		if err != nil {
			return fmt.Errorf("%w: installed credential %s: %v", ErrLiveCredentials, entry.Name(), err)
		}
		clear(content)
	}
	return nil
}

// CredentialChildRequest is the bounded service-user preflight request passed
// over stdin to the same executable. It carries file paths, never secrets.
type CredentialChildRequest struct {
	Config              natscell.Config `json:"config"`
	UID                 uint32          `json:"uid"`
	GID                 uint32          `json:"gid"`
	ResponseKeyFile     string          `json:"responseKeyFile"`
	BrokerTicketKeyFile string          `json:"brokerTicketKeyFile"`
}

func runCredentialChild(ctx context.Context, wire []byte, uid, gid uint32) error {
	command := exec.CommandContext(ctx, "/proc/self/exe", "bootstrap-credential-check")
	command.Stdin = bytes.NewReader(wire)
	command.Stdout = io.Discard
	command.Stderr = io.Discard
	command.Env = []string{"PATH=/usr/bin:/bin"}
	command.SysProcAttr = &syscall.SysProcAttr{Credential: &syscall.Credential{
		Uid: uid, Gid: gid, Groups: []uint32{},
	}}
	if err := command.Run(); err != nil {
		return fmt.Errorf("service credential child exited unsuccessfully: %w", err)
	}
	return nil
}

// RunCredentialValidationChild is the hidden, read-only same-binary command.
// The parent supplies only configuration and expected service identity; no
// secret bytes or cloud authority are passed through stdin.
func RunCredentialValidationChild(input io.Reader, validateControllerKeys func(CredentialChildRequest) error) error {
	const maximum = 1 << 20
	wire, err := io.ReadAll(io.LimitReader(input, maximum+1))
	if err != nil || len(wire) == 0 || len(wire) > maximum {
		return ErrLiveCredentials
	}
	var request CredentialChildRequest
	if err := protocol.DecodeStrict(wire, &request, maximum); err != nil ||
		request.UID == 0 || request.GID == 0 ||
		request.ResponseKeyFile == "" || request.BrokerTicketKeyFile == "" || validateControllerKeys == nil ||
		os.Geteuid() != int(request.UID) || os.Getegid() != int(request.GID) {
		return ErrLiveCredentials
	}
	groups, err := os.Getgroups()
	if err != nil || len(groups) != 0 {
		return ErrLiveCredentials
	}
	if err := natscell.ValidateProductionCredentials(request.Config); err != nil {
		return err
	}
	return validateControllerKeys(request)
}

func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

func ValidateProductionCredentials(cfg Config) error {
	if cfg.Embedded == nil || cfg.ClientRole != "" && cfg.ClientRole != "controller" {
		return errors.New("controller credential preflight requires a production embedded broker")
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	e := cfg.Embedded
	operator, systemRaw, cellRaw, _, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return err
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil {
		return fmt.Errorf("decode system account JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil {
		return fmt.Errorf("decode cell account JWT: %w", err)
	}
	for label, claim := range map[string]jwt.Claims{"operator": operator, "system": system, "cell": cell} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s JWT is not currently valid", label)
		}
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, system.Subject); err != nil {
		return err
	}
	systemUser, _, err := credentialUser(e.SystemCredentialsFile)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return errors.New("controller credentials do not belong to the regional cell account")
	}
	for label, claim := range map[string]*jwt.UserClaims{"system": systemUser, "controller": controller} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s user JWT is not currently valid", label)
		}
	}
	if err := ValidateBrokerControllerCredentials(cfg.CredentialsFile, cfg.Cell, cfg.Instance); err != nil {
		return err
	}
	// The optional membership user is checked at admission, not first at
	// shutdown when it is needed for the metadata step-down.
	if e.MembershipCredentialsFile != "" {
		if err := ValidateMembershipCredentials(e.MembershipCredentialsFile, cfg.Cell, system.Subject); err != nil {
			return err
		}
	}
	for label, files := range map[string]TLSFiles{"client": cfg.TLS, "listener": e.TLS, "route": e.RouteTLS} {
		if err := validateCurrentTLSFiles(files, label); err != nil {
			return fmt.Errorf("%s TLS material: %w", label, err)
		}
	}
	if cfg.Replicas > 1 {
		password, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return fmt.Errorf("NATS route secret: %w", err)
		}
		defer clear(password)
		if len(strings.TrimSpace(string(password))) < 16 {
			return errors.New("NATS route secret is too short")
		}
	}
	return nil
}

func validateCurrentTLSFiles(files TLSFiles, role string) error {
	config, err := loadTLS(files, false)
	if err != nil {
		return err
	}
	if len(config.Certificates) != 1 || len(config.Certificates[0].Certificate) == 0 {
		return errors.New("TLS certificate chain is missing")
	}
	leaf, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
	if err != nil {
		return fmt.Errorf("parse TLS leaf certificate: %w", err)
	}
	return verifyTLSLeaf(leaf, config.Certificates[0].Certificate[1:], config.RootCAs, role)
}

// verifyTLSLeaf checks that a leaf is current and chains to roots for each
// usage its role needs: client, listener or route (both ends).
func verifyTLSLeaf(leaf *x509.Certificate, chain [][]byte, roots *x509.CertPool, role string) error {
	intermediates := x509.NewCertPool()
	for _, der := range chain {
		certificate, err := x509.ParseCertificate(der)
		if err != nil {
			return fmt.Errorf("parse TLS intermediate certificate: %w", err)
		}
		intermediates.AddCert(certificate)
	}
	var usages []x509.ExtKeyUsage
	switch role {
	case "client":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
	case "listener":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}
	case "route":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}
	default:
		return fmt.Errorf("unsupported TLS certificate role %q", role)
	}
	for _, usage := range usages {
		if _, err := leaf.Verify(x509.VerifyOptions{
			Roots: roots, Intermediates: intermediates, CurrentTime: time.Now(),
			KeyUsages: []x509.ExtKeyUsage{usage},
		}); err != nil {
			return fmt.Errorf("verify current TLS certificate chain: %w", err)
		}
	}
	return nil
}

func loadOperatorAccounts(e *Embedded) (*jwt.OperatorClaims, string, string, string, string, error) {
	operatorRaw, err := readSignedJWT(e.OperatorJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional operator JWT: %w", err)
	}
	operator, err := jwt.DecodeOperatorClaims(operatorRaw)
	if err != nil || !nkeys.IsValidPublicOperatorKey(operator.Subject) ||
		!nkeys.IsValidPublicAccountKey(operator.SystemAccount) {
		return nil, "", "", "", "", errors.New("regional operator JWT is invalid")
	}
	systemRaw, err := readSignedJWT(e.SystemJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional system JWT: %w", err)
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil || system.Subject != operator.SystemAccount || !operator.DidSign(system) {
		return nil, "", "", "", "", errors.New("regional system account JWT is invalid")
	}
	cellRaw, err := readSignedJWT(e.CellJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional cell JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil || !nkeys.IsValidPublicAccountKey(cell.Subject) ||
		cell.Subject == system.Subject || !operator.DidSign(cell) {
		return nil, "", "", "", "", errors.New("regional cell account JWT is invalid")
	}
	return operator, systemRaw, cellRaw, system.Subject, cell.Subject, nil
}

func credentialUser(path string) (*jwt.UserClaims, string, error) {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return nil, "", err
	}
	defer clear(data)
	return credentialUserBytes(data)
}

func credentialUserBytes(data []byte) (*jwt.UserClaims, string, error) {
	raw, err := nkeys.ParseDecoratedJWT(data)
	if err != nil {
		return nil, "", err
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return nil, "", err
	}
	pair, err := nkeys.ParseDecoratedUserNKey(data)
	if err != nil {
		return nil, "", err
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil || public != claim.Subject {
		return nil, "", errors.New("regional credential seed and user JWT differ")
	}
	if claim.BearerToken || claim.ProxyRequired || len(claim.Src) != 0 ||
		len(claim.AllowedConnectionTypes) != 0 && !claim.AllowedConnectionTypes.Contains(jwt.ConnectionTypeInProcess) {
		return nil, "", errors.New("regional JWT depends on client metadata unavailable through the bridge")
	}
	return claim, public, nil
}

func loadTLS(files TLSFiles, serverSide bool) (*tls.Config, error) {
	key, err := readPrivateFile(files.KeyFile, 64<<10)
	if err != nil {
		return nil, fmt.Errorf("NATS TLS private key: %w", err)
	}
	clear(key)
	certificate, err := tls.LoadX509KeyPair(files.CertFile, files.KeyFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS certificate: %w", err)
	}
	ca, err := os.ReadFile(files.CAFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS CA: %w", err)
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(ca) {
		return nil, errors.New("NATS CA file has no certificates")
	}
	config := &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}, RootCAs: roots}
	if serverSide {
		config.ClientCAs = roots
		config.ClientAuth = tls.RequireAndVerifyClientCert
	}
	return config, nil
}

func readPrivateFile(path string, limit int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("secret must be a regular file readable only by its owner")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("secret must be owned by this process user")
	}
	if info.Size() > limit {
		return nil, errors.New("secret file is too large")
	}
	data, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > limit {
		clear(data)
		return nil, errors.New("secret file is too large")
	}
	return data, nil
}

func readPrivateKey(path string) (ed25519.PrivateKey, error) {
	if path == "" {
		return nil, errors.New("private identity key file is required")
	}
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, fmt.Errorf("open private key: %w", err)
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat private key: %w", err)
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("private key must be a regular file readable only by its owner")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("private key must be owned by this process user")
	}
	data, err := io.ReadAll(io.LimitReader(file, 128))
	if err != nil {
		return nil, fmt.Errorf("read private key: %w", err)
	}
	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
	if err != nil {
		return nil, fmt.Errorf("decode private key: %w", err)
	}
	if len(decoded) != ed25519.PrivateKeySize {
		return nil, errors.New("private key must contain 64 Ed25519 bytes")
	}
	return ed25519.PrivateKey(decoded), nil
}

func brokerTicketKeys(cfg Config) (ed25519.PrivateKey, ed25519.PublicKey, error) {
	if cfg.NATS.Embedded == nil || cfg.Controller.BrokerTicketKeyFile == "" || cfg.NATS.Embedded.TicketPublicKeyFile == "" {
		return nil, nil, errors.New("production broker ticket signing and pinned public keys are required")
	}
	private, err := readPrivateKey(cfg.Controller.BrokerTicketKeyFile)
	if err != nil {
		return nil, nil, fmt.Errorf("read broker ticket signing key: %w", err)
	}
	publicRaw, err := os.ReadFile(cfg.NATS.Embedded.TicketPublicKeyFile)
	if err != nil {
		return nil, nil, fmt.Errorf("read pinned broker ticket key: %w", err)
	}
	public, err := decodePublicKey(string(publicRaw))
	if err != nil || !bytes.Equal(public, private.Public().(ed25519.PublicKey)) {
		return nil, nil, errors.New("pinned broker ticket key does not match the private signer")
	}
	return private, public, nil
}

